## Part 2: Designing the Task Class

### Basic Class Structure

```python
class Task:
    """Represents a single task in our management system."""

    def __init__(self, task_id, name, priority=3, description=""):
        self.task_id = task_id
        self.name = name
        self.priority = priority
        self.description = description
        self.complete = False
        self.tags = []

    def mark_complete(self):
        self.complete = True

    def mark_pending(self):
        self.complete = False

    def add_tag(self, tag):
        if tag not in self.tags:
            self.tags.append(tag)

    def __repr__(self):
        status = "✓" if self.complete else "○"
        return f"Task({self.task_id}, '{self.name}', {status})"
```

### Adding Validation

Real-world applications need input validation. Let's enhance our class:

```python
class Task:
    VALID_PRIORITIES = range(1, 6)

    def __init__(self, task_id, name, priority=3, description=""):
        if not name or not isinstance(name, str):
            raise ValueError("Task name must be a non-empty string")

        if priority not in self.VALID_PRIORITIES:
            raise ValueError(f"Priority must be 1-5, got {priority}")

        self.task_id = task_id
        self.name = name
        self.priority = priority
        self.description = description
        self.complete = False
        self.tags = []

    def mark_complete(self):
        if self.complete:
            raise RuntimeError("Task is already complete")
        self.complete = True

    def mark_pending(self):
        self.complete = False

    def add_tag(self, tag):
        if not isinstance(tag, str):
            raise TypeError("Tag must be a string")
        if tag not in self.tags:
            self.tags.append(tag)

    def remove_tag(self, tag):
        if tag in self.tags:
            self.tags.remove(tag)

    def __repr__(self):
        status = "✓" if self.complete else "○"
        return f"Task({self.task_id}, '{self.name}', {status})"
```

